/* ================= 3) WITHDRAWAL: aksi nyata dua arah ================= */
const WD_FLOW = ['pending', 'approved', 'disbursed'];
const wdWs = w => ({ Travel: 'travel', Vendor: 'vendor', Affiliate: 'affiliate' })[w.partyType];
const wdHist = (w, state, by, reason, extra) => { w.history = w.history || []; w.history.push(Object.assign({ state, by, reason: reason || '', ts: nowTs() }, extra || {})); };
function wdApproval(w) { return APPROVALS.find(a => a.type === 'withdrawal' && (a.wd === w.id || (!a.wd && a.requester === w.party && a.amount === w.amount))); }
function wdSyncApproval(w, v, reason) { const a = wdApproval(w); if (!a) return; const map = { approved: 'approved', disbursed: 'approved', rejected: 'rejected', cancelled: 'rejected', needs_revision: 'needs_revision', hold: 'in_progress', pending: 'waiting' }; const s = map[v]; if (!s || a.status === s) return; a.status = s; a.history = a.history || []; a.history.push({ t: 'Withdrawal → ' + stLbl(v), ts: nowTs(), tone: s === 'approved' ? 'ok' : s === 'rejected' ? 'bad' : 'warn', by: 'Finance', reason }); }
/* dana kembali ke pihak saat ditolak / dibatalkan */
function wdRefund(w) { if (w.refunded) return; w.refunded = true; const ws = wdWs(w); if (ws === 'affiliate') { (w.comms || []).forEach(id => { const c = COMMISSIONS.find(x => x.id === id); if (c && c.state === 'paid') c.state = 'approved'; }); } if (typeof recompute === 'function') recompute(); }
function wdAdminActs(w) { const b = (a, cls, label) => permBtn('finance.withdrawal', label, `data-act="wd-do" data-a="${a}" data-id="${w.id}" data-mut`, 'sm ' + cls);
  return ({ pending: [b('approve', 'primary', t('approve')), b('revise', '', L3(['Kembalikan', 'Return', 'إرجاع'])), b('hold', '', L3(['Tahan', 'Hold', 'تعليق'])), b('reject', 'badb', t('reject'))], hold: [b('release', 'primary', L3(['Lepas tahan', 'Release', 'إلغاء التعليق'])), b('reject', 'badb', t('reject'))], approved: [b('pay', 'primary', L3(['Tandai ditransfer', 'Mark transferred', 'تم التحويل'])), b('unapprove', '', L3(['Batalkan persetujuan', 'Revoke approval', 'إلغاء الموافقة']))] })[w.state] || []; }
function wdTimeline(w) { const H = (w.history && w.history.length) ? w.history : [{ state: 'pending', by: w.party, ts: w.ts }]; return `<ul class="tl">${H.map(h => `<li><span class="dotc ${stTone2(h.state) === 'ok' ? 'ok' : stTone2(h.state) === 'bad' ? 'bad' : 'info'}"></span><b>${esc(stLbl(h.state))}</b><div class="muted" style="font-size:12px">${esc(h.by || '')} · ${fDT(h.ts)}${h.reason ? '<br>“' + esc(h.reason) + '”' : ''}${h.ref ? '<br>Ref ' + esc(h.ref) : ''}</div></li>`).join('')}</ul>`; }
function wdDetail(w, mode) { const proof = UPLOADS.find(u => u.kind === 'wdproof' && u.ref === w.id);
  return `<section class="panel" style="padding:12px 14px;margin-bottom:14px">${lifeBar(WD_FLOW, ['needs_revision', 'hold'].includes(w.state) ? 'pending' : ['rejected', 'cancelled'].includes(w.state) ? 'pending' : w.state, ['needs_revision', 'hold', 'rejected', 'cancelled'].includes(w.state) ? w.state : null)}</section>
  <div class="grid g2">${pnl('Detail', `<dl class="dl"><dt>ID</dt><dd class="mono">${w.id}</dd><dt>${L3(['Pihak', 'Party', 'الطرف'])}</dt><dd>${esc(w.party)} <span class="chip">${w.partyType}</span></dd><dt>${L3(['Jumlah', 'Amount', 'المبلغ'])}</dt><dd class="tnum"><b>${money(w.amount, true)}</b></dd><dt>Basis</dt><dd>${esc(w.basis || '—')}</dd><dt>${L3(['Rekening tujuan', 'Payout account', 'الحساب'])}</dt><dd>${w.bank ? esc(w.bank.name + ' · ' + w.bank.no + ' · a.n. ' + w.bank.holder) : '—'}</dd><dt>${L3(['Catatan', 'Note', 'ملاحظة'])}</dt><dd>${esc(w.note || '—')}</dd><dt>${L3(['Dikirim ulang', 'Resubmitted', 'أُعيد'])}</dt><dd>${fN(w.resubmits || 0)}×</dd><dt>${t('status')}</dt><dd>${st(w.state)}</dd>${w.transferRef ? `<dt>Ref transfer</dt><dd class="mono">${esc(w.transferRef)}</dd>` : ''}</dl>${proof ? upRow(proof) : ''}`, { icon: 'arrowur' })}${pnl(L3(['Riwayat', 'History', 'السجل']), wdTimeline(w), { icon: 'history' })}</div>`; }

/* admin: daftar + detail */
