decideApproval = function (id, v, reason) { const a = APPROVALS.find(x => x.id === id); if (a && a.type === 'withdrawal') { const w = WITHDRAWALS.find(x => x.id === a.wd) || WITHDRAWALS.find(x => x.party === a.requester && x.state === 'pending'); if (w && ['pending', 'hold'].includes(w.state)) { const to = v === 'approved' ? 'approved' : v === 'rejected' ? 'rejected' : v === 'needs_revision' ? 'needs_revision' : 'hold'; const prev = w.state; w.state = to; wdHist(w, to, 'Finance · Approval Center', reason); if (to === 'rejected') wdRefund(w); audit('Admin Pusat', 'withdrawal.' + to, 'Withdrawal/' + w.id, 'success', { before: prev, after: to, reason }); a.wd = w.id; a.type = 'withdrawal_done'; const r = _decideApproval(id, v, reason); a.type = 'withdrawal'; return r; } } return _decideApproval(id, v, reason); };

