reroute('/p/affiliate/payout', () => { const a = me('affiliate'); const ap = wdBalance('affiliate', a);
  return { html: `<div class="page">${pHead('affiliate', 'Payout', L3(['Komisi yang disetujui dapat dicairkan. Finance bisa menyetujui, mengembalikan untuk diperbaiki, atau menolak.', 'Approved commission can be paid out. Finance can approve, return for fixes, or reject.', 'الصرف.']), `<button class="btn primary" data-act="wd-req" data-ws="affiliate" ${ap > 0 ? '' : `aria-disabled="true" data-tip="${esc(L3(['Belum ada komisi disetujui', 'No approved commission yet', 'لا عمولة']))}"`}>${ic('arrowur')}${L3(['Cairkan', 'Pay out', 'صرف'])} · ${money(ap)}</button>`)}<section class="panel">${wdPartyTable('affiliate', a)}</section></div>` }; });

A['file-dl'] = async el => { const up = UPLOADS.find(u => u.id === el.dataset.id); if (!up) return; try { const dls = await window.claude.use('downloads'); if (!dls) return; const u = await fileURL(up.id); const bin = Uint8Array.from(atob(u.split(',')[1]), c => c.charCodeAt(0)); const ext = /pdf/.test(up.mime) ? 'pdf' : /png/.test(up.mime) ? 'png' : 'jpg'; const base = (up.name || 'file').replace(/\.[^.]+$/, ''); await dls.save({ filename: base + '.' + ext, data: new Blob([bin]) }); } catch (e) { if (e && e.code !== 'declined') toast('warn', L3(['Unduhan tidak tersedia', 'Download unavailable', 'غير متاح']), (e && e.message) || ''); } };

/* ================= Admin & Mitra/Agen: lihat data lengkap pendaftar ================= */
function registrantBlock(b, mode) { const g = bookingProgress(b);
  return `<div style="margin-top:14px">${kpiRow([{ k: L3(['Data jamaah lengkap', 'Pilgrim data complete', 'البيانات']), v: g.data, icon: 'users' }, { k: L3(['Dokumen terverifikasi', 'Documents verified', 'المستندات']), v: g.docs, icon: 'filecheck' }, { k: L3(['Terbayar', 'Paid', 'مدفوع']), v: g.pay, icon: 'wallet' }, { k: L3(['Menunggu dicek Travel', 'Awaiting Travel review', 'بانتظار']), v: fN(g.waiting), icon: 'clock' }])}</div>
  <div style="margin-top:14px">${pnl(L3(['Data jamaah', 'Pilgrim data', 'بيانات المعتمرين']), pilgrimTable(b, mode !== 'admin'), { raw: true, icon: 'users' })}</div>
  <div class="grid g12" style="margin-top:14px"><div class="c7">${pnl(L3(['Dokumen', 'Documents', 'المستندات']), docsGrid(b, mode), { icon: 'folder' })}</div><div class="c5">${pnl(L3(['Pembayaran & bukti bayar', 'Payments & proofs', 'المدفوعات']), payProofs(b, mode), { icon: 'card' })}</div></div>`; }
(() => { const R = ROUTES.find(x => x.pattern === '/booking/:id'); if (!R) return; const prev = R.fn;
  reroute('/booking/:id', p => { const out = prev(p); const b = bookingById(p.id); if (!b || !out || !out.html) return out; const i = out.html.lastIndexOf('</div>'); out.html = out.html.slice(0, i) + registrantBlock(b, 'admin') + out.html.slice(i); return out; }); })();
['mitra', 'agen'].forEach(ws => {
  route('/p/' + ws + '/bookings/:id', p => { const b = bookingById(p.id); const mine = b && myBookings(ws).some(x => x.id === b.id); if (!mine) return { html: `<div class="page">${stateBlock('noperm', { desc: L3(['Booking ini bukan pendaftaran Anda.', 'This booking is not one you registered.', 'ليس لك.']) })}</div>` };
    return { html: `<div class="page">${phead({ crumbs: [[L3(WS[ws].label), WS[ws].home], ['Booking', '/p/' + ws + '/bookings'], [b.id, '']], title: b.id + ' · ' + esc(trvName(b.traveler)), desc: esc((pkgById(b.pkg) || {}).name || '') + ' · ' + b.pax + ' pax · ' + fD(b.dep) + ' · ' + stLbl(b.state) })}${portalStatusBanner(ws)}<p class="muted" style="margin:0 0 4px">${L3(['Lengkapi data & unggah dokumen jamaah yang Anda daftarkan. Travel memverifikasi setiap dokumen.', 'Complete the data & upload documents for pilgrims you registered. The Travel verifies each document.', 'أكمل البيانات.'])}</p>${registrantBlock(b, 'party')}</div>` }; });
});
(() => { const f = maBookings; maBookings = function (ws) { let h = f(ws); myBookings(ws).forEach(b => { h = h.replace(`<td class="mono">${b.id}`, `<td class="mono"><a href="#/p/${ws}/bookings/${b.id}">${b.id}</a>`); }); return h; }; })();
